     1→/**
     2→ * ClaudeScript 코드 생성기
     3→ * 검증된 & 타입 검사된 ClaudeScript AST를 FreeLang VT 바이트코드로 컴파일합니다
     4→ *
     5→ * 출력 형식: S-expression (Lisp-like syntax)
     6→ * 예:
     7→ *   (let x 42)
     8→ *   (if (> x 0) (println "positive") (println "non-positive"))
     9→ *   (defn add (a b) (+ a b))
    10→ */
    11→
    12→import { Program, Statement, Expression, TypeSpec, FunctionDef } from "./ast";
    13→
    14→export interface CodeGenResult {
    15→  code: string;
    16→  success: boolean;
    17→  errors: string[];
    18→}
    19→
    20→export class CodeGenerator {
    21→  private code: string[] = [];
    22→  private indentLevel: number = 0;
    23→  private errors: string[] = [];
    24→  private functionRegistry: Map<string, FunctionDef> = new Map();
    25→  private builtins: Set<string> = new Set([
    26→    "println",
    27→    "print",
    28→    "to_string",
    29→    "to_i32",
    30→    "to_f64",
    31→    "length",
    32→    "push",
    33→    "pop",
    34→    "get",
    35→    "set",
    36→  ]);
    37→
    38→  /**
    39→   * 프로그램 전체 코드 생성
    40→   */
    41→  generate(program: Program): CodeGenResult {
    42→    this.code = [];
    43→    this.indentLevel = 0;
    44→    this.errors = [];
    45→    this.functionRegistry.clear();
    46→
    47→    try {
    48→      // 1단계: 함수 정의 수집
    49→      for (const def of program.definitions) {
    50→        this.functionRegistry.set(def.name, def);
    51→      }
    52→
    53→      // 2단계: 함수 정의 코드 생성
    54→      for (const def of program.definitions) {
    55→        this.generateFunctionDef(def);
    56→      }
    57→
    58→      // 3단계: 메인 프로그램 코드 생성
    59→      this.emitLine("; === Main Program ===");
    60→      for (const stmt of program.instructions) {
    61→        this.generateStatement(stmt);
    62→      }
    63→
    64→      return {
    65→        code: this.code.join("\n"),
    66→        success: this.errors.length === 0,
    67→        errors: this.errors,
    68→      };
    69→    } catch (e) {
    70→      this.errors.push(`Code generation failed: ${e}`);
    71→      return {
    72→        code: "",
    73→        success: false,
    74→        errors: this.errors,
    75→      };
    76→    }
    77→  }
    78→
    79→  /**
    80→   * 함수 정의 생성
    81→   */
    82→  private generateFunctionDef(def: FunctionDef) {
    83→    const paramNames = def.params.map((p) => p.name);
    84→    this.emit(`(defn ${def.name} (${paramNames.join(" ")})`);
    85→    this.indentLevel++;
    86→
    87→    // 함수 본체
    88→    for (const stmt of def.body) {
    89→      this.generateStatement(stmt);
    90→    }
    91→
    92→    this.indentLevel--;
    93→    this.emit(")");
    94→  }
    95→
    96→  /**
    97→   * 문장 코드 생성
    98→   */
    99→  private generateStatement(stmt: Statement): void {
   100→    const indent = "  ".repeat(this.indentLevel);
   101→
   102→    switch (stmt.type) {
   103→      case "var":
   104→        // (let name value)
   105→        this.emitLine(`(let ${stmt.name} ${this.generateExpression(stmt.value)})`);
   106→        break;
   107→
   108→      case "assign":
   109→        // (set! name value)
   110→        this.emitLine(`(set! ${stmt.name} ${this.generateExpression(stmt.value)})`);
   111→        break;
   112→
   113→      case "return":
   114→        // (return value) → VT에서는 마지막 값이 반환
   115→        this.emitLine(this.generateExpression(stmt.value));
   116→        break;
   117→
   118→      case "call":
   119→        // (function-name arg1 arg2 ...)
   120→        const callExpr = this.generateExpression(stmt);
   121→        if (stmt.assign_to) {
   122→          this.emitLine(`(let ${stmt.assign_to} ${callExpr})`);
   123→        } else {
   124→          this.emitLine(callExpr);
   125→        }
   126→        break;
   127→
   128→      case "condition":
   129→        // (if test then-body else-body)
   130→        this.generateCondition(stmt);
   131→        break;
   132→
   133→      case "for":
   134→        // (loop-range var start end body)
   135→        this.generateFor(stmt);
   136→        break;
   137→
   138→      case "while":
   139→        // (while condition body)
   140→        this.generateWhile(stmt);
   141→        break;
   142→
   143→      case "match":
   144→        // (match value cases...)
   145→        this.generateMatch(stmt);
   146→        break;
   147→
   148→      case "try":
   149→        // (try-catch body catch-var catch-body finally-body)
   150→        this.generateTry(stmt);
   151→        break;
   152→
   153→      case "throw":
   154→        // (throw error-type message)
   155→        this.emitLine(
   156→          `(throw ${stmt.error_type} "${this.generateExpression(stmt.message)}")`
   157→        );
   158→        break;
   159→
   160→      default:
   161→        this.errors.push(`Unknown statement type: ${(stmt as any).type}`);
   162→    }
   163→  }
   164→
   165→  /**
   166→   * 조건문 생성
   167→   */
   168→  private generateCondition(stmt: any): void {
   169→    const test = this.generateExpression(stmt.test);
   170→    this.emitLine(`(if ${test}`);
   171→    this.indentLevel++;
   172→
   173→    // then 블록
   174→    for (const s of stmt.then) {
   175→      this.generateStatement(s);
   176→    }
   177→
   178→    this.indentLevel--;
   179→
   180→    // else 블록
   181→    if (stmt.else && stmt.else.length > 0) {
   182→      this.indentLevel++;
   183→      for (const s of stmt.else) {
   184→        this.generateStatement(s);
   185→      }
   186→      this.indentLevel--;
   187→    }
   188→
   189→    this.emitLine(")");
   190→  }
   191→
   192→  /**
   193→   * For 루프 생성
   194→   */
   195→  private generateFor(stmt: any): void {
   196→    const start = this.generateExpression(stmt.range.start);
   197→    const end = this.generateExpression(stmt.range.end);
   198→
   199→    this.emitLine(`(loop-range ${stmt.variable} ${start} ${end}`);
   200→    this.indentLevel++;
   201→
   202→    for (const s of stmt.body) {
   203→      this.generateStatement(s);
   204→    }
   205→
   206→    this.indentLevel--;
   207→    this.emitLine(")");
   208→  }
   209→
   210→  /**
   211→   * While 루프 생성
   212→   */
   213→  private generateWhile(stmt: any): void {
   214→    const condition = this.generateExpression(stmt.condition);
   215→    this.emitLine(`(while ${condition}`);
   216→    this.indentLevel++;
   217→
   218→    for (const s of stmt.body) {
   219→      this.generateStatement(s);
   220→    }
   221→
   222→    this.indentLevel--;
   223→    this.emitLine(")");
   224→  }
   225→
   226→  /**
   227→   * Match 표현식 생성
   228→   */
   229→  private generateMatch(stmt: any): void {
   230→    const value = this.generateExpression(stmt.value);
   231→    this.emitLine(`(match ${value}`);
   232→    this.indentLevel++;
   233→
   234→    for (const caseItem of stmt.cases) {
   235→      if (caseItem.pattern === "Some") {
   236→        this.emitLine(`(Some ${caseItem.bind || "_"}`);
   237→        this.indentLevel++;
   238→        for (const s of caseItem.body) {
   239→          this.generateStatement(s);
   240→        }
   241→        this.indentLevel--;
   242→        this.emit(")");
   243→      } else if (caseItem.pattern === "None") {
   244→        this.emitLine(`(None`);
   245→        this.indentLevel++;
   246→        for (const s of caseItem.body) {
   247→          this.generateStatement(s);
   248→        }
   249→        this.indentLevel--;
   250→        this.emit(")");
   251→      }
   252→    }
   253→
   254→    this.indentLevel--;
   255→    this.emitLine(")");
   256→  }
   257→
   258→  /**
   259→   * Try/Catch 생성
   260→   */
   261→  private generateTry(stmt: any): void {
   262→    const indent = "  ".repeat(this.indentLevel);
   263→
   264→    this.code.push(`${indent}(try-catch`);
   265→    this.indentLevel++;
   266→
   267→    // try 본체
   268→    for (const s of stmt.body) {
   269→      this.generateStatement(s);
   270→    }
   271→
   272→    this.indentLevel--;
   273→
   274→    // catch 블록
   275→    if (stmt.catch) {
   276→      const catchIndent = "  ".repeat(this.indentLevel);
   277→      this.code.push(`${catchIndent}(catch ${stmt.catch.error_var}`);
   278→      this.indentLevel++;
   279→      for (const s of stmt.catch.body) {
   280→        this.generateStatement(s);
   281→      }
   282→      this.indentLevel--;
   283→      const endIndent = "  ".repeat(this.indentLevel);
   284→      this.code.push(`${endIndent})`);
   285→    }
   286→
   287→    // finally 블록
   288→    if (stmt.finally && stmt.finally.length > 0) {
   289→      const finallyIndent = "  ".repeat(this.indentLevel);
   290→      this.code.push(`${finallyIndent}(finally`);
   291→      this.indentLevel++;
   292→      for (const s of stmt.finally) {
   293→        this.generateStatement(s);
   294→      }
   295→      this.indentLevel--;
   296→      const endIndent = "  ".repeat(this.indentLevel);
   297→      this.code.push(`${endIndent})`);
   298→    }
   299→
   300→    const finalIndent = "  ".repeat(this.indentLevel);
   301→    this.code.push(`${finalIndent})`);
   302→  }
   303→
   304→  /**
   305→   * 표현식 코드 생성
   306→   */
   307→  private generateExpression(expr: Expression | any): string {
   308→    switch (expr.type) {
   309→      case "literal":
   310→        return this.generateLiteral(expr);
   311→
   312→      case "ref":
   313→        return expr.name;
   314→
   315→      case "binary_op":
   316→        return this.generateBinaryOp(expr);
   317→
   318→      case "unary_op":
   319→        return this.generateUnaryOp(expr);
   320→
   321→      case "index":
   322→        // (array-get array index)
   323→        return `(array-get ${this.generateExpression(expr.array)} ${this.generateExpression(
   324→          expr.index
   325→        )})`;
   326→
   327→      case "field":
   328→        // (field-get object field)
   329→        return `(field-get ${this.generateExpression(expr.object)} ${expr.field})`;
   330→
   331→      case "call":
   332→        return this.generateCall(expr);
   333→
   334→      case "some":
   335→        // (some value)
   336→        return `(some ${this.generateExpression(expr.value)})`;
   337→
   338→      case "none":
   339→        // (none)
   340→        return "(none)";
   341→
   342→      case "literal_array":
   343→        // (array-create elem1 elem2 ...)
   344→        const values = expr.values.map((v: Expression) => this.generateExpression(v));
   345→        return `(array-create ${values.join(" ")})`;
   346→
   347→      case "literal_object":
   348→        // (object-create (field1 val1) (field2 val2) ...)
   349→        const fields = Object.entries(expr.fields).map(
   350→          ([k, v]) => `(${k} ${this.generateExpression(v as Expression)})`
   351→        );
   352→        return `(object-create ${fields.join(" ")})`;
   353→
   354→      default:
   355→        this.errors.push(`Unknown expression type: ${(expr as any).type}`);
   356→        return "nil";
   357→    }
   358→  }
   359→
   360→  /**
   361→   * 리터럴 값 생성
   362→   */
   363→  private generateLiteral(expr: any): string {
   364→    switch (expr.value_type) {
   365→      case "i32":
   366→      case "i64":
   367→      case "f64":
   368→        return String(expr.value);
   369→
   370→      case "string":
   371→        return `"${expr.value.replace(/"/g, '\\"')}"`;
   372→
   373→      case "bool":
   374→        return expr.value ? "#t" : "#f";
   375→
   376→      case "none":
   377→        return "(none)";
   378→
   379→      default:
   380→        return String(expr.value);
   381→    }
   382→  }
   383→
   384→  /**
   385→   * 이항 연산자 생성
   386→   */
   387→  private generateBinaryOp(expr: any): string {
   388→    const left = this.generateExpression(expr.left);
   389→    const right = this.generateExpression(expr.right);
   390→    const op = this.mapOperator(expr.op);
   391→    return `(${op} ${left} ${right})`;
   392→  }
   393→
   394→  /**
   395→   * 단항 연산자 생성
   396→   */
   397→  private generateUnaryOp(expr: any): string {
   398→    const operand = this.generateExpression(expr.operand);
   399→    const op = this.mapOperator(expr.op);
   400→    return `(${op} ${operand})`;
   401→  }
   402→
   403→  /**
   404→   * 함수 호출 생성
   405→   */
   406→  private generateCall(expr: any): string {
   407→    const args = expr.args.map((a: Expression) => this.generateExpression(a)).join(" ");
   408→
   409→    // 내장 함수 처리
   410→    if (this.builtins.has(expr.function)) {
   411→      return `(${expr.function} ${args})`.trim();
   412→    }
   413→
   414→    // 사용자 정의 함수
   415→    if (this.functionRegistry.has(expr.function)) {
   416→      return `(${expr.function} ${args})`.trim();
   417→    }
   418→
   419→    this.errors.push(`Unknown function: ${expr.function}`);
   420→    return `(${expr.function} ${args})`.trim();
   421→  }
   422→
   423→  /**
   424→   * 연산자를 VT 형식으로 매핑
   425→   */
   426→  private mapOperator(op: string): string {
   427→    const opMap: { [key: string]: string } = {
   428→      "+": "+",
   429→      "-": "-",
   430→      "*": "*",
   431→      "/": "/",
   432→      "%": "%",
   433→      "==": "=",
   434→      "!=": "!=",
   435→      "<": "<",
   436→      ">": ">",
   437→      "<=": "<=",
   438→      ">=": ">=",
   439→      "&&": "and",
   440→      "||": "or",
   441→      "!": "not",
   442→    };
   443→    return opMap[op] || op;
   444→  }
   445→
   446→  /**
   447→   * 코드 줄 추가 (자동 들여쓰기)
   448→   */
   449→  private emitLine(text: string): void {
   450→    const indent = "  ".repeat(this.indentLevel);
   451→    this.code.push(indent + text);
   452→  }
   453→
   454→  /**
   455→   * 코드 추가 (들여쓰기 없음)
   456→   */
   457→  private emit(text: string): void {
   458→    if (this.code.length > 0) {
   459→      this.code[this.code.length - 1] += text;
   460→    } else {
   461→      this.code.push(text);
   462→    }
   463→  }
   464→}
   465→
   466→/**
   467→ * 간편 함수: 프로그램을 바로 코드로 생성
   468→ */
   469→export function generate(program: Program): CodeGenResult {
   470→  const generator = new CodeGenerator();
   471→  return generator.generate(program);
   472→}
