     1→/**
     2→ * ClaudeScript AST 타입 정의
     3→ * 이 파일은 JSON AST를 TypeScript 타입으로 변환합니다
     4→ */
     5→
     6→// ==================== 기본 타입 ====================
     7→
     8→export type TypeSpec =
     9→  | PrimitiveType
    10→  | ArrayType
    11→  | OptionType
    12→  | ObjectType
    13→  | MapType
    14→  | GenericRef;
    15→
    16→export interface PrimitiveType {
    17→  base: "i32" | "i64" | "f64" | "string" | "bool";
    18→}
    19→
    20→export interface ArrayType {
    21→  base: "Array";
    22→  element_type: TypeSpec;
    23→}
    24→
    25→export interface OptionType {
    26→  base: "Option";
    27→  element_type: TypeSpec;
    28→}
    29→
    30→export interface ObjectType {
    31→  base: "Object";
    32→  value_type: TypeSpec;
    33→}
    34→
    35→export interface MapType {
    36→  base: "Map";
    37→  key_type: TypeSpec;
    38→  value_type: TypeSpec;
    39→}
    40→
    41→export interface GenericRef {
    42→  base: string;  // T, U, K, V 등
    43→}
    44→
    45→// ==================== 리터럴 ====================
    46→
    47→export interface Literal {
    48→  type: "literal";
    49→  value_type: string;
    50→  value: any;
    51→}
    52→
    53→export interface LiteralArray {
    54→  type: "literal_array";
    55→  element_type: TypeSpec;
    56→  values: Expression[];
    57→}
    58→
    59→// ==================== 참조 ====================
    60→
    61→export interface Ref {
    62→  type: "ref";
    63→  name: string;
    64→}
    65→
    66→export interface Index {
    67→  type: "index";
    68→  array: Expression;
    69→  index: Expression;
    70→}
    71→
    72→export interface Field {
    73→  type: "field";
    74→  object: Expression;
    75→  key: string;
    76→}
    77→
    78→// ==================== 연산 ====================
    79→
    80→export interface BinaryOp {
    81→  type: "binary_op";
    82→  op: "+" | "-" | "*" | "/" | "%" | "==" | "!=" | "<" | ">" | "<=" | ">=" | "&&" | "||";
    83→  left: Expression;
    84→  right: Expression;
    85→}
    86→
    87→export interface UnaryOp {
    88→  type: "unary_op";
    89→  op: "-" | "!";
    90→  operand: Expression;
    91→}
    92→
    93→// ==================== 함수 호출 ====================
    94→
    95→export interface Call {
    96→  type: "call";
    97→  function: string;
    98→  args: Expression[];
    99→  assign_to?: string;
   100→}
   101→
   102→export interface MethodCall {
   103→  type: "method_call";
   104→  object: Expression;
   105→  method: string;
   106→  args: Expression[];
   107→  assign_to?: string;
   108→}
   109→
   110→// ==================== 패턴 매칭 ====================
   111→
   112→export interface Some {
   113→  type: "some";
   114→  value: Expression;
   115→}
   116→
   117→export interface None {
   118→  type: "none";
   119→}
   120→
   121→export interface MatchCase {
   122→  pattern: "Some" | "None";
   123→  bind?: string;  // Some의 경우 바인딩된 변수 이름
   124→  body: Statement[];
   125→}
   126→
   127→export interface Match {
   128→  type: "match";
   129→  value: Expression;
   130→  cases: MatchCase[];
   131→}
   132→
   133→// ==================== 표현식 ====================
   134→
   135→export type Expression =
   136→  | Literal
   137→  | LiteralArray
   138→  | Ref
   139→  | Index
   140→  | Field
   141→  | BinaryOp
   142→  | UnaryOp
   143→  | Call
   144→  | MethodCall
   145→  | Match
   146→  | Some
   147→  | None
   148→  | Lambda;
   149→
   150→// ==================== 문장 ====================
   151→
   152→export interface VarDecl {
   153→  type: "var";
   154→  name: string;
   155→  value_type?: TypeSpec;
   156→  value: Expression;
   157→}
   158→
   159→export interface Assign {
   160→  type: "assign";
   161→  name: string;
   162→  value: Expression;
   163→}
   164→
   165→export interface Return {
   166→  type: "return";
   167→  value: Expression;
   168→}
   169→
   170→export interface Condition {
   171→  type: "condition";
   172→  test: Expression;
   173→  then: Statement[];
   174→  else?: Statement[];
   175→}
   176→
   177→export interface For {
   178→  type: "for";
   179→  variable: string;
   180→  range: {
   181→    start: Expression;
   182→    end: Expression;
   183→  };
   184→  body: Statement[];
   185→}
   186→
   187→export interface While {
   188→  type: "while";
   189→  condition: Expression;
   190→  body: Statement[];
   191→}
   192→
   193→export interface Try {
   194→  type: "try";
   195→  body: Statement[];
   196→  catch?: {
   197→    error_var: string;
   198→    error_type: string;
   199→    body: Statement[];
   200→  };
   201→  finally?: Statement[];
   202→}
   203→
   204→export interface Throw {
   205→  type: "throw";
   206→  error_type: string;
   207→  message: Expression;
   208→}
   209→
   210→export type Statement =
   211→  | VarDecl
   212→  | Assign
   213→  | Return
   214→  | Condition
   215→  | For
   216→  | While
   217→  | Try
   218→  | Throw
   219→  | Call
   220→  | MethodCall
   221→  | Match;
   222→
   223→// ==================== 함수 정의 ====================
   224→
   225→export interface FunctionParam {
   226→  name: string;
   227→  type: TypeSpec;
   228→}
   229→
   230→export interface FunctionDef {
   231→  type: "function";
