    33→  /**
    34→   * 프로그램 전체 타입 검사
    35→   */
    36→  checkProgram(ast: Program): TypeCheckResult {
    37→    this.errors = [];
    38→    this.variables = {};
    39→    this.functions = {};
    40→    this.scopes = [{}];  // 전역 스코프
    41→
    42→    // 1단계: 함수 정의 수집
    43→    this.collectFunctionDefinitions(ast.definitions);
    44→
    45→    // 2단계: 함수 본체 검사
    46→    for (const def of ast.definitions) {
    47→      this.checkFunctionDef(def);
    48→    }
    49→
    50→    // 3단계: 실행 명령 검사
    51→    for (let i = 0; i < ast.instructions.length; i++) {
    52→      this.checkStatement(ast.instructions[i], i);
    53→    }
    54→
    55→    const typeInfoMap = new Map<string, TypeSpec>(Object.entries(this.variables));
    56→    return {
    57→      valid: this.errors.length === 0,
    58→      errors: this.errors,
    59→      typeInfo: typeInfoMap,
    60→    };
    61→  }
    62→
    63→  /**
    64→   * 함수 정의 수집 (선언-사용 순서 보장)
    65→   */
    66→  private collectFunctionDefinitions(definitions: FunctionDef[]) {
    67→    for (const def of definitions) {
    68→      this.functions[def.name] = {
    69→        params: def.params,
    70→        return_type: def.return_type,
    71→      };
    72→    }
    73→  }
    74→
    75→  /**
    76→   * 함수 정의 검사
    77→   */
    78→  private checkFunctionDef(def: FunctionDef) {
    79→    // 함수 파라미터를 함수 스코프에 추가
    80→    const funcScope: TypeInfo = {};
    81→    for (const param of def.params) {
    82→      funcScope[param.name] = param.type;
    83→    }
    84→
    85→    // 이전 스코프 저장
    86→    const prevScope = this.scopes[this.scopes.length - 1];
    87→    this.scopes[this.scopes.length - 1] = funcScope;
    88→
    89→    // 함수 본체 검사
    90→    for (let i = 0; i < def.body.length; i++) {
    91→      this.checkStatement(def.body[i], i, `function ${def.name}`);
    92→    }
    93→
    94→    // 스코프 복원
    95→    this.scopes[this.scopes.length - 1] = prevScope;
    96→  }
