    98→  /**
    99→   * 문장 검사
   100→   */
   101→  private checkStatement(stmt: any, index: number, context: string = "instructions") {
   102→    const stmtPrefix = `${context}[${index}]`;
   103→
   104→    switch (stmt.type) {
