   108→      case "assign":
   109→        this.checkAssign(stmt, stmtPrefix);
   110→        break;
   111→      case "return":
   112→        this.checkReturn(stmt, stmtPrefix);
   113→        break;
   114→      case "condition":
   115→        this.checkCondition(stmt, stmtPrefix);
   116→        break;
   117→      case "for":
   118→        this.checkFor(stmt, stmtPrefix);
   119→        break;
   120→      case "while":
   121→        this.checkWhile(stmt, stmtPrefix);
   122→        break;
   123→      case "match":
   124→        this.checkMatch(stmt, stmtPrefix);
   125→        break;
   126→      case "call":
   127→      case "method_call":
   128→        this.checkCall(stmt, stmtPrefix);
   129→        break;
   130→      case "try":
   131→        this.checkTry(stmt, stmtPrefix);
   132→        break;
   133→    }
   134→  }
   135→
   136→  /**
   137→   * 변수 선언 검사
   138→   */
   139→  private checkVarDecl(stmt: any, prefix: string) {
   140→    const varType = stmt.value_type || this.inferType(stmt.value);
   141→
   142→    if (!varType) {
   143→      this.errors.push({
   144→        message: `${prefix}: ${stmt.name}의 타입을 추론할 수 없습니다`,
   145→        code: "TYPE_INFERENCE_FAILED",
   146→      });
   147→      return;
   148→    }
   149→
   150→    // 값의 타입 검사
   151→    const valueType = this.getExpressionType(stmt.value);
   152→    if (valueType && !this.isCompatible(varType, valueType)) {
   153→      this.errors.push({
   154→        message: `${prefix}: 타입 불일치 - ${this.typeToString(varType)}을(를) 기대했으나 ${this.typeToString(valueType)} 받음`,
   155→        code: "TYPE_MISMATCH",
   156→      });
   157→      return;
   158→    }
   159→
   160→    // 변수 등록
   161→    this.setVariable(stmt.name, varType);
   162→  }
   163→
   164→  /**
   165→   * 변수 재할당 검사
   166→   */
   167→  private checkAssign(stmt: any, prefix: string) {
   168→    const varType = this.getVariable(stmt.name);
   169→    if (!varType) {
   170→      this.errors.push({
   171→        message: `${prefix}: 정의되지 않은 변수 "${stmt.name}"`,
   172→        code: "UNDEFINED_VARIABLE",
   173→      });
   174→      return;
   175→    }
   176→
   177→    const valueType = this.getExpressionType(stmt.value);
   178→    if (valueType && !this.isCompatible(varType, valueType)) {
   179→      this.errors.push({
   180→        message: `${prefix}: 타입 불일치 - ${this.typeToString(varType)}을(를) 기대했으나 ${this.typeToString(valueType)} 받음`,
   181→        code: "TYPE_MISMATCH",
   182→      });
   183→    }
   184→  }
   185→
   186→  /**
   187→   * Return 문 검사
   188→   */
   189→  private checkReturn(stmt: any, prefix: string) {
   190→    if (stmt.value) {
   191→      const returnType = this.getExpressionType(stmt.value);
   192→      // 실제 함수의 반환 타입과 비교는 나중에 함수 컨텍스트에서 수행
   193→    }
   194→  }
   195→
   196→  /**
   197→   * 조건문 검사
   198→   */
   199→  private checkCondition(stmt: any, prefix: string) {
   200→    // 조건식이 bool 타입인지 검사
   201→    const testType = this.getExpressionType(stmt.test);
   202→    if (testType && !this.isBoolType(testType)) {
   203→      this.errors.push({
   204→        message: `${prefix}: 조건식은 bool 타입이어야 합니다. 받은 타입: ${this.typeToString(testType)}`,
   205→        code: "CONDITION_TYPE_ERROR",
   206→      });
   207→    }
   208→
   209→    // then 블록 검사
   210→    for (let i = 0; i < stmt.then.length; i++) {
   211→      this.checkStatement(stmt.then[i], i, `${prefix}.then`);
   212→    }
   213→
   214→    // else 블록 검사
   215→    if (stmt.else) {
   216→      for (let i = 0; i < stmt.else.length; i++) {
   217→        this.checkStatement(stmt.else[i], i, `${prefix}.else`);
   218→      }
   219→    }
   220→  }
   221→
   222→  /**
   223→   * For 루프 검사
   224→   */
   225→  private checkFor(stmt: any, prefix: string) {
