   227→    const startType = this.getExpressionType(stmt.range.start);
   228→    const endType = this.getExpressionType(stmt.range.end);
   229→
   230→    if (startType && !this.isIntegerType(startType)) {
   231→      this.errors.push({
   232→        message: `${prefix}: 루프 범위의 시작은 정수 타입이어야 합니다`,
   233→        code: "RANGE_TYPE_ERROR",
   234→      });
   235→    }
   236→
   237→    if (endType && !this.isIntegerType(endType)) {
   238→      this.errors.push({
   239→        message: `${prefix}: 루프 범위의 끝은 정수 타입이어야 합니다`,
   240→        code: "RANGE_TYPE_ERROR",
   241→      });
   242→    }
   243→
   244→    // 루프 변수를 정수 타입으로 등록
   245→    this.setVariable(stmt.variable, { base: "i32" });
   246→
   247→    // 루프 본체 검사
   248→    for (let i = 0; i < stmt.body.length; i++) {
   249→      this.checkStatement(stmt.body[i], i, `${prefix}.body`);
   250→    }
   251→  }
   252→
   253→  /**
   254→   * While 루프 검사
   255→   */
   256→  private checkWhile(stmt: any, prefix: string) {
   257→    const condType = this.getExpressionType(stmt.condition);
   258→    if (condType && !this.isBoolType(condType)) {
   259→      this.errors.push({
   260→        message: `${prefix}: 루프 조건은 bool 타입이어야 합니다`,
   261→        code: "CONDITION_TYPE_ERROR",
   262→      });
   263→    }
   264→
   265→    // 루프 본체 검사
   266→    for (let i = 0; i < stmt.body.length; i++) {
   267→      this.checkStatement(stmt.body[i], i, `${prefix}.body`);
   268→    }
   269→  }
   270→
   271→  /**
   272→   * Match (패턴 매칭) 검사
   273→   */
   274→  private checkMatch(stmt: any, prefix: string) {
   275→    const valueType = this.getExpressionType(stmt.value);
   276→
   277→    // Option 타입인지 확인
   278→    if (
   279→      !valueType ||
   280→      valueType.base !== "Option"
   281→    ) {
   282→      this.errors.push({
   283→        message: `${prefix}: match는 Option 타입에만 사용 가능합니다. 받은 타입: ${this.typeToString(valueType || { base: "unknown" })}`,
   284→        code: "MATCH_TYPE_ERROR",
   285→      });
   286→    }
   287→
   288→    // 각 케이스 검사
   289→    for (const caseItem of stmt.cases) {
   290→      if (caseItem.bind && valueType && valueType.base === "Option") {
   291→        // Some 케이스: 바인딩된 변수의 타입 설정
   292→        const elemType = this.getTypeProperty(valueType, "element_type") || { base: "unknown" };
   293→        this.setVariable(caseItem.bind, elemType);
   294→      }
   295→
   296→      for (let i = 0; i < caseItem.body.length; i++) {
   297→        this.checkStatement(caseItem.body[i], i, `${prefix}.case(${caseItem.pattern})`);
   298→      }
   299→    }
   300→  }
   301→
   302→  /**
   303→   * 함수 호출 검사
   304→   */
   305→  private checkCall(stmt: any, prefix: string) {
   306→    const funcInfo = this.functions[stmt.function];
   307→
   308→    if (!funcInfo && !this.isBuiltinFunction(stmt.function)) {
   309→      this.errors.push({
   310→        message: `${prefix}: 정의되지 않은 함수 "${stmt.function}"`,
   311→        code: "UNDEFINED_FUNCTION",
   312→      });
   313→      return;
   314→    }
   315→
   316→    if (funcInfo) {
   317→      // 인자 개수 검사
   318→      if (stmt.args.length !== funcInfo.params.length) {
   319→        this.errors.push({
   320→          message: `${prefix}: ${stmt.function}은 ${funcInfo.params.length}개의 인자를 기대하나 ${stmt.args.length}개 받음`,
   321→          code: "ARGUMENT_COUNT_MISMATCH",
   322→        });
   323→      }
   324→
   325→      // 인자 타입 검사
   326→      for (let i = 0; i < Math.min(stmt.args.length, funcInfo.params.length); i++) {
   327→        const argType = this.getExpressionType(stmt.args[i]);
   328→        const paramType = funcInfo.params[i].type;
   329→
   330→        if (argType && !this.isCompatible(paramType, argType)) {
   331→          this.errors.push({
   332→            message: `${prefix}: 인자 ${i + 1}의 타입 불일치 - ${this.typeToString(paramType)}을(를) 기대했으나 ${this.typeToString(argType)} 받음`,
   333→            code: "ARGUMENT_TYPE_MISMATCH",
   334→          });
   335→        }
   336→      }
   337→    }
   338→
   339→    // 반환값이 할당되는 경우
   340→    if (stmt.assign_to && funcInfo) {
   341→      this.setVariable(stmt.assign_to, funcInfo.return_type);
   342→    }
   343→  }
   344→
   345→  /**
   346→   * Try/Catch 검사
   347→   */
   348→  private checkTry(stmt: any, prefix: string) {
   349→    // try 블록
   350→    for (let i = 0; i < stmt.body.length; i++) {
   351→      this.checkStatement(stmt.body[i], i, `${prefix}.try`);
   352→    }
   353→
   354→    // catch 블록
   355→    if (stmt.catch) {
   356→      this.setVariable(stmt.catch.error_var, { base: "string" });
   357→      for (let i = 0; i < stmt.catch.body.length; i++) {
   358→        this.checkStatement(stmt.catch.body[i], i, `${prefix}.catch`);
   359→      }
   360→    }
   361→
   362→    // finally 블록
   363→    if (stmt.finally) {
   364→      for (let i = 0; i < stmt.finally.length; i++) {
   365→        this.checkStatement(stmt.finally[i], i, `${prefix}.finally`);
   366→      }
   367→    }
   368→  }
