   370→  /**
   371→   * 표현식의 타입 얻기
   372→   */
   373→  private getExpressionType(expr: any): TypeSpec | null {
   374→    if (!expr) return null;
   375→
   376→    switch (expr.type) {
   377→      case "literal":
   378→        return { base: expr.value_type };
   379→      case "ref":
   380→        return this.getVariable(expr.name);
   381→      case "binary_op":
   382→        return this.getBinaryOpType(expr);
   383→      case "unary_op":
   384→        return this.getUnaryOpType(expr);
   385→      case "call":
   386→        return this.getCallReturnType(expr);
   387→      case "index":
   388→        return this.getIndexType(expr);
   389→      case "some": {
   390→        const val = this.getExpressionType(expr.value) || { base: "unknown" };
   391→        const result: any = { base: "Option", element_type: val };
   392→        return result as TypeSpec;
   393→      }
   394→      case "none": {
   395→        const result: any = { base: "Option", element_type: { base: "unknown" } };
   396→        return result as TypeSpec;
   397→      }
   398→      case "literal_array":
   399→        return {
   400→          base: "Array",
   401→          element_type: expr.element_type,
   402→        };
   403→      default:
   404→        return null;
   405→    }
   406→  }
   407→
   408→  /**
   409→   * 이항 연산 타입
   410→   */
   411→  private getBinaryOpType(expr: any): TypeSpec | null {
   412→    const leftType = this.getExpressionType(expr.left);
   413→    const rightType = this.getExpressionType(expr.right);
   414→
   415→    if (!leftType || !rightType) return null;
   416→
   417→    // 산술 연산
   418→    if (["+", "-", "*", "/", "%"].includes(expr.op)) {
   419→      if (this.isCompatible(leftType, rightType)) {
   420→        return leftType;
   421→      }
   422→      return null;
   423→    }
   424→
   425→    // 비교 연산
   426→    if (["==", "!=", "<", ">", "<=", ">="].includes(expr.op)) {
   427→      return { base: "bool" };
   428→    }
   429→
   430→    // 논리 연산
   431→    if (["&&", "||"].includes(expr.op)) {
   432→      return { base: "bool" };
   433→    }
   434→
   435→    return null;
   436→  }
   437→
   438→  private getTypeProperty(type: TypeSpec, prop: string): TypeSpec | undefined {
   439→    const anyType = type as any;
   440→    return anyType[prop];
   441→  }
   442→
   443→  /**
   444→   * 단항 연산 타입
   445→   */
   446→  private getUnaryOpType(expr: any): TypeSpec | null {
   447→    const operandType = this.getExpressionType(expr.operand);
   448→
   449→    if (!operandType) return null;
   450→
   451→    if (expr.op === "-") {
   452→      return operandType;  // 부호 반전은 같은 타입 반환
   453→    }
   454→
   455→    if (expr.op === "!") {
   456→      return { base: "bool" };  // 논리 부정은 bool 반환
   457→    }
   458→
   459→    return null;
   460→  }
   461→
   462→  /**
   463→   * 함수 호출의 반환 타입
   464→   */
   465→  private getCallReturnType(expr: any): TypeSpec | null {
   466→    const funcInfo = this.functions[expr.function];
   467→    if (funcInfo) {
   468→      return funcInfo.return_type;
   469→    }
   470→
   471→    // 내장 함수
   472→    if (expr.function === "to_string") return { base: "string" };
   473→    if (expr.function === "to_i32") return { base: "i32" };
   474→    if (expr.function === "to_f64") return { base: "f64" };
   475→    if (expr.function === "length") return { base: "i32" };
   476→
   477→    return null;
   478→  }
   479→
   480→  /**
   481→   * 배열 인덱싱 타입
   482→   */
   483→  private getIndexType(expr: any): TypeSpec | null {
   484→    const arrayType = this.getExpressionType(expr.array);
   485→    const indexType = this.getExpressionType(expr.index);
   486→
   487→    if (!arrayType || !indexType) return null;
   488→
   489→    // 인덱스는 정수여야 함
   490→    if (!this.isIntegerType(indexType)) {
   491→      this.errors.push({
   492→        message: `배열 인덱스는 정수 타입이어야 합니다. 받은 타입: ${this.typeToString(indexType)}`,
   493→        code: "INDEX_TYPE_ERROR",
   494→      });
   495→      return null;
   496→    }
   497→
   498→    // 배열 타입이어야 함
   499→    if (arrayType.base !== "Array") {
   500→      this.errors.push({
   501→        message: `배열 인덱싱은 Array 타입에만 사용 가능합니다. 받은 타입: ${this.typeToString(arrayType)}`,
   502→        code: "INDEX_ON_NON_ARRAY",
   503→      });
   504→      return null;
   505→    }
   506→
   507→    // 원소 타입 반환
   508→    const elemType = this.getTypeProperty(arrayType, "element_type") || { base: "unknown" };
   509→    return elemType;
   510→  }
   511→
   512→  /**
   513→   * 타입 추론
   514→   */
   515→  private inferType(expr: any): TypeSpec | null {
   516→    if (expr.type === "literal") {
   517→      return { base: expr.value_type };
   518→    }
   519→    if (expr.type === "literal_array") {
   520→      return {
   521→        base: "Array",
   522→        element_type: expr.element_type,
   523→      };
   524→    }
   525→    return null;
   526→  }
   527→
   528→  /**
   529→   * 타입 호환성 검사
   530→   */
   531→  private isCompatible(expected: TypeSpec, actual: TypeSpec): boolean {
   532→    // 같은 기본 타입
   533→    if (expected.base === actual.base) {
   534→      // 복합 타입의 경우 재귀적으로 검사
   535→      if (expected.base === "Array" && actual.base === "Array") {
   536→        const expectedElem = this.getTypeProperty(expected, "element_type") || { base: "unknown" };
   537→        const actualElem = this.getTypeProperty(actual, "element_type") || { base: "unknown" };
   538→        return this.isCompatible(expectedElem, actualElem);
   539→      }
   540→      if (expected.base === "Option" && actual.base === "Option") {
   541→        const expectedElem = this.getTypeProperty(expected, "element_type") || { base: "unknown" };
   542→        const actualElem = this.getTypeProperty(actual, "element_type") || { base: "unknown" };
   543→        return this.isCompatible(expectedElem, actualElem);
   544→      }
   545→      return true;
   546→    }
   547→
   548→    // 암묵적 변환 금지
   549→    return false;
   550→  }
