   607→  /**
   608→   * 타입을 문자열로 변환
   609→   */
   610→  private typeToString(type: TypeSpec): string {
   611→    if (type.base === "Array") {
   612→      const elemType = this.getTypeProperty(type, "element_type") || { base: "unknown" };
   613→      return `Array<${this.typeToString(elemType)}>`;
   614→    }
   615→    if (type.base === "Option") {
   616→      const elemType = this.getTypeProperty(type, "element_type") || { base: "unknown" };
   617→      return `Option<${this.typeToString(elemType)}>`;
   618→    }
   619→    if (type.base === "Map") {
